import re
s=open('prisma/schema.prisma').read()
models=re.findall(r'^model (\w+) \{(.*?)^\}',s,re.S|re.M)
allm={n for n,_ in models}
cy=[(n,b) for n,b in models if re.search(r'cyrus|modbuilder|modBuilder|ModBuild|ModProject',n,re.I)]
print(len(models),'models;',len(cy),'cyrus/modbuilder')
for n,b in cy:
  rels=[]
  for l in b.splitlines():
    m=re.match(r'\s*(\w+)\s+(\w+)(\[\])?\??.*@relation',l)
    if m: rels.append((m.group(1),m.group(2)))
    elif re.match(r'\s*(\w+)\s+(\w+)(\[\])?\??\s*$',l.split('//')[0]+' ') :
      m2=re.match(r'\s*(\w+)\s+(\w+)',l)
      if m2 and m2.group(2) in allm: rels.append((m2.group(1),m2.group(2)))
  print(n,[r for r in rels])
# Non-cyrus models referencing cyrus
EOF

